    #[test]
    fn ordinary_map_set_get_string_bytecode_executes_and_rejects_anchor_tampering() {
        let (_, checked) = parse_and_check(ORDINARY_MAP_SET_GET_STRING_SOURCE)
            .expect("the shared Set/Get-String source fixture checks");
        let owner = crate::core::NodeId("function:main".into());
        let mir = MirProgram::from_checked_program_map_set_get_string_result(&checked, &owner)
            .expect("the exact Checker receipt materializes canonical String Set/Get MIR");
        let bytecode = super::compile_mir_program_with_map_set_get_string_route(&checked, &mir)
            .expect("the dedicated String source-bound adapter compiles the exact route");
        let has_set = bytecode.functions.iter().any(|function| {
            function
                .code
                .iter()
                .any(|op| matches!(op, Op::MirOrdinaryMapOwnedAnyV2SetStringResult { .. }))
        });
        let has_get = bytecode.functions.iter().any(|function| {
            function
                .code
                .iter()
                .any(|op| matches!(op, Op::MirOrdinaryMapOwnedAnyV2GetStringResult { .. }))
        });
        assert!(
            has_set && has_get,
            "the two String-specific opcodes are present"
        );
        assert_eq!(
            BytecodeVM::new(bytecode.clone())
                .run_value()
                .expect("Set copies the String and borrowed Get returns a detached copy"),
            Value::Int(42)
        );

        let mut changed_bytecode = (*bytecode).clone();
        let mut changed_get = false;
        for op in &mut changed_bytecode.functions[0].code {
            if let Op::MirOrdinaryMapOwnedAnyV2GetStringResult { rd, ra, .. } = op {
                *rd = *ra;
                changed_get = true;
                break;
            }
        }
        assert!(changed_get, "the source-bound String Get opcode is present");
        assert!(BytecodeVM::new(Arc::new(changed_bytecode))
            .run_value_for_ordinary_map_failure_model_test()
            .is_err());

        let mut changed_set = (*bytecode).clone();
        let mut changed_set_alias = false;
        for op in &mut changed_set.functions[0].code {
            if let Op::MirOrdinaryMapOwnedAnyV2SetStringResult { rd, ra, .. } = op {
                *rd = *ra;
                changed_set_alias = true;
                break;
            }
        }
        assert!(
            changed_set_alias,
            "the source-bound String Set opcode is present"
        );
        assert!(BytecodeVM::new(Arc::new(changed_set))
            .run_value_for_ordinary_map_failure_model_test()
            .is_err());

        let mut changed_type_hash = (*bytecode).clone();
        let set_hash_constant = changed_type_hash.functions[0]
            .code
            .iter()
            .find_map(|op| match op {
                Op::MirOrdinaryMapOwnedAnyV2SetStringResult {
                    string_type_desc_hash,
                    ..
                } => Some(*string_type_desc_hash as usize),
                _ => None,
            })
            .expect("String Set descriptor-hash operand");
        changed_type_hash.functions[0].constants[set_hash_constant] =
            ConstValue::Str("forged-string-descriptor-hash".into());
        assert!(BytecodeVM::new(Arc::new(changed_type_hash))
            .run_value_for_ordinary_map_failure_model_test()
            .is_err());

        let mut missing_anchor = (*bytecode).clone();
        missing_anchor.canonical_map_any_owner_v1_receipt = None;
        assert!(BytecodeVM::new(Arc::new(missing_anchor))
            .run_value_for_ordinary_map_failure_model_test()
            .is_err());

        let (_, i32_checked) = parse_and_check(include_str!(
            "../../../tests/fixtures/mir_ordinary_map_owned_any_v2_set_get_i32_lineage.mimi"
        ))
        .expect("the separate i32 source fixture checks");
        let i32_owner = crate::core::NodeId("function:main".into());
        let i32_mir =
            MirProgram::from_checked_program_map_set_get_i32_result(&i32_checked, &i32_owner)
                .expect("the separate i32 Checker receipt materializes its own MIR");
        let i32_bytecode =
            super::compile_mir_program_with_map_set_get_i32_route(&i32_checked, &i32_mir)
                .expect("the separate i32 source-bound adapter emits its own anchor");
        let mut transplanted_i32_anchor = (*bytecode).clone();
        transplanted_i32_anchor.canonical_map_any_owner_v1_receipt =
            i32_bytecode.canonical_map_any_owner_v1_receipt.clone();
        assert!(BytecodeVM::new(Arc::new(transplanted_i32_anchor))
            .run_value_for_ordinary_map_failure_model_test()
            .is_err());

        let changed_source = ORDINARY_MAP_SET_GET_STRING_SOURCE.replacen(
            "map_get_string(updated, \"answer\")",
            "map_get_string(updated, \"other\")",
            1,
        );
        let (_, changed_checked) =
            parse_and_check(&changed_source).expect("near-miss source remains well-typed");
        assert!(
            super::compile_mir_program_with_map_set_get_string_route(&changed_checked, &mir)
                .is_err()
        );
    }

    fn compile_ordinary_map_owner_observer_v1(
        source: &str,
    ) -> (MirProgram, Arc<crate::interp::bytecode::BytecodeProgram>) {
        let (_, checked) = parse_and_check(source)
            .expect("ordinary Map owner observer v1 source parses and type-checks");
        let mir = MirProgram::from_checked_program(&checked)
            .expect("ordinary Map owner observer v1 source lowers to MIR");
        let route_receipt = mir
            .ordinary_map_owner_lifecycle_observer_v1_route_receipt()
            .expect("ordinary Map owner observer v1 route receipt validates independently");
        assert_eq!(
            route_receipt.profile,
            crate::core::mir::CanonicalMirRouteProfile::OrdinaryMapOwnerLifecycleObserverV1
                .as_str()
        );
        let bytecode = compile_mir_program_with_route_receipt(&mir, &route_receipt)
            .expect("exact ordinary Map owner observer v1 route compiles");
        (mir, bytecode)
    }

    #[test]
    fn ordinary_map_owner_observer_v1_json_is_canonical_and_borrows_live_root() {
        let source = r#"
            func main() -> i32 {
                println("prefix must not escape preflight")
                match map_new() {
                    Ok(empty) => {
                    let key = "a\"\\b"
                    let value = "line1\nline2\t\"\\tail"
                match map_set(empty, "z-last", "last") {
                    Ok(later_key) => {
                match map_set(later_key, key, value) {
                    Ok(root) => {
                            let hit_before = has_key(root, key)
                            let miss_before = has_key(root, "missing")
                            println(hit_before)
                            println(miss_before)
                            let json = to_json(root)
                            println(root)
                            let hit_after = has_key(root, key)
                            let miss_after = has_key(root, "missing")
                            let size_after = map_size(root)
                            println(hit_after)
                            println(miss_after)
                            println(size_after)
                            drop(empty)
                            drop(later_key)
                            drop(root)
                            println(json)
                            drop(json)
                            size_after
                    },
                    Err(status) => {
                    drop(empty)
                    drop(later_key)
                    status
                    },
                }
                    },
                    Err(status) => {
                    drop(empty)
                    status
                    },
                }
                    },
                    Err(status) => {
                    status
                    },
                }
            }
        "#;
        let (mir, bytecode) = compile_ordinary_map_owner_observer_v1(source);
        assert!(mir.functions().values().any(|function| {
            function.blocks.values().any(|block| {
                block.instructions.iter().any(|instruction| {
                    matches!(
                        &instruction.kind,
                        MirInstructionKind::OrdinaryMapOwnerLifecycleObserverToJson { .. }
                    )
                })
            })
        }));
        assert!(bytecode.functions.iter().any(|function| {
            function
                .code
                .iter()
                .any(|op| matches!(op, Op::MirOrdinaryMapOwnerLifecycleObserverV1ToJson { .. }))
        }));
        assert!(bytecode.functions.iter().any(|function| {
            function
                .code
                .iter()
                .any(|op| matches!(op, Op::MirOrdinaryMapOwnerLifecycleObserverV1Println { .. }))
        }));

        let expected = concat!(
            "prefix must not escape preflight\ntrue\nfalse\n",
            r#"{"a\"\\b":"line1\nline2\t\"\\tail","z-last":"last"}"#,
            "\n",
            "true\nfalse\n2\n",
            r#"{"a\"\\b":"line1\nline2\t\"\\tail","z-last":"last"}"#,
            "\n"
        );
        let mut vm = BytecodeVM::new(bytecode);
        assert!(matches!(
            vm.run_value()
                .expect("observer bytecode borrows root and returns owned JSON"),
            Value::Int(2)
        ));
        assert_eq!(vm.take_stdout(), expected);
    }

    #[test]
    fn ordinary_map_owner_observer_v1_allocation_failures_are_e0800_and_atomic() {
        let println_source = r#"
            func main() -> i32 {
    match map_new() {
        Ok(root) => {
                    println(root)
                    drop(root)
                    0
        },
        Err(status) => {
        status
        },
    }
            }
        "#;
        let (_, println_bytecode) = compile_ordinary_map_owner_observer_v1(println_source);

        // Empty-root Println has four fallible publication points: the JSON
        // opening/closing buffer reservations, newline staging, and captured
        // stdout reservation. Failure at any point must leave output empty.
        for failure_stage in 0..4 {
            let mut vm = BytecodeVM::new(println_bytecode.clone());
            vm.enable_stdout_capture();
            let (result, attempts, triggered, stdout) =
                crate::runtime::with_ordinary_map_owned_get_allocation_failure_for_test(
                    failure_stage,
                    || {
                        let result = vm.run_value();
                        (
                            result,
                            crate::runtime::ordinary_map_owned_get_allocation_attempts_for_test(),
                            crate::runtime::ordinary_map_owned_get_allocation_failure_triggered_for_test(),
                            vm.take_stdout(),
                        )
                    },
                );
            let error = result.expect_err("injected observer allocation must fail");
            assert_eq!(error.code(), "E0800", "stage {failure_stage}: {error}");
            assert!(
                error
                    .message()
                    .contains("ordinary Map owner lifecycle observer v1"),
                "stage {failure_stage}: {error}"
            );
            assert!(triggered, "stage {failure_stage}");
            assert_eq!(attempts, failure_stage + 1, "stage {failure_stage}");
            assert!(stdout.is_empty(), "stage {failure_stage}: partial stdout");
        }

        let to_json_source = r#"
            func main() -> i32 {
    match map_new() {
        Ok(empty) => {
        match map_set(empty, "answer", "value") {
            Ok(root) => {
                    let json = to_json(root)
                    println(json)
                    drop(json)
                    drop(root)
                    drop(empty)
                    0
            },
            Err(status) => {
            drop(empty)
            status
            },
        }
        },
        Err(status) => {
        status
        },
    }
            }
        "#;
        let (_, to_json_bytecode) = compile_ordinary_map_owner_observer_v1(to_json_source);

        // Stage zero fails the first JSON reserve. Stage five reaches the
        // owned VM String publication checkpoint after all five JSON buffer
        // reserves have succeeded, before assigning the result register.
        for failure_stage in [0, 5] {
            let mut vm = BytecodeVM::new(to_json_bytecode.clone());
            vm.enable_stdout_capture();
            let (result, attempts, triggered, stdout) =
                crate::runtime::with_ordinary_map_owned_get_allocation_failure_for_test(
                    failure_stage,
                    || {
                        let result = vm.run_value();
                        (
                            result,
                            crate::runtime::ordinary_map_owned_get_allocation_attempts_for_test(),
                            crate::runtime::ordinary_map_owned_get_allocation_failure_triggered_for_test(),
                            vm.take_stdout(),
                        )
                    },
                );
            let error = result.expect_err("injected ToJson allocation must fail");
            assert_eq!(error.code(), "E0800", "stage {failure_stage}: {error}");
            assert!(
                error
                    .message()
                    .contains("ordinary Map owner lifecycle observer v1"),
                "stage {failure_stage}: {error}"
            );
            assert!(triggered, "stage {failure_stage}");
            assert_eq!(attempts, failure_stage + 1, "stage {failure_stage}");
            assert!(stdout.is_empty(), "stage {failure_stage}: output escaped");
        }
    }

    #[test]
    fn ordinary_map_owner_observer_v1_tampering_fails_before_first_output() {
        let source = r#"
            func main() -> i32 {
                println("prefix must not escape preflight")
                match map_new() {
                    Ok(empty) => {
                match map_set(empty, "answer", "value") {
                    Ok(root) => {
                        println(root)
                        drop(empty)
                        drop(root)
                        0
                    },
                    Err(status) => {
                    drop(empty)
                    status
                    },
                }
                    },
                    Err(status) => {
                    status
                    },
                }
            }
        "#;
        let (_, bytecode) = compile_ordinary_map_owner_observer_v1(source);

        let mut operand_tampered = bytecode.clone();
        let program = Arc::make_mut(&mut operand_tampered);
        let op = program
            .functions
            .iter_mut()
            .flat_map(|function| function.code.iter_mut())
            .find(|op| matches!(op, Op::MirOrdinaryMapOwnerLifecycleObserverV1Println { .. }))
            .expect("emitted dedicated observer Println opcode");
        let Op::MirOrdinaryMapOwnerLifecycleObserverV1Println { ra, .. } = op else {
            unreachable!();
        };
        *ra = u16::MAX;
        let mut vm = BytecodeVM::new(operand_tampered);
        let error = vm
            .run_value()
            .expect_err("observer operand tampering must fail whole-program preflight");
        assert!(
            error
                .message()
                .contains(
                    "ordinary Map owner lifecycle v1 bytecode disagrees with its independent Checker receipt snapshot"
                ),
            "unexpected observer operand tamper error: {error}"
        );
        assert!(vm.take_stdout().is_empty(), "preflight must precede output");

        let mut builtin_table_tampered = bytecode.clone();
        let program = Arc::make_mut(&mut builtin_table_tampered);
        let builtin = program
            .functions
            .iter()
            .flat_map(|function| function.code.iter())
            .find_map(|op| match op {
                Op::CallBuiltin { builtin, .. } => Some(*builtin),
                _ => None,
            })
            .expect("generic prefix println has a builtin-table reference");
        program.builtin_names[builtin as usize] = "tampered_observer_prefix".into();
        let mut vm = BytecodeVM::new(builtin_table_tampered);
        let error = vm
            .run_value()
            .expect_err("observer program builtin-table tampering must fail preflight");
        assert!(
            error
                .message()
                .contains("ordinary Map owner observer v1 anchor"),
            "unexpected observer builtin-table tamper error: {error}"
        );
        assert!(vm.take_stdout().is_empty(), "preflight must precede output");

        let mut profile_tampered = bytecode;
        Arc::make_mut(&mut profile_tampered)
            .canonical_map_any_owner_v1_receipt
            .as_mut()
            .expect("observer route receipt carrier")
            .corrupt_ordinary_map_owner_observer_v1_anchor_for_test_only();
        let mut vm = BytecodeVM::new(profile_tampered);
        let error = vm
            .run_value()
            .expect_err("observer route profile tampering must fail preflight");
        assert!(
            error
                .message()
                .contains("ordinary Map owner observer v1 route profile"),
            "unexpected observer route tamper error: {error}"
        );
        assert!(vm.take_stdout().is_empty(), "preflight must precede output");
    }

    #[test]
    fn ordinary_map_owner_observer_v1_rejects_wrong_or_foreign_route_receipts() {
        let source = r#"
            func main() -> i32 {
    match map_new() {
        Ok(empty) => {
        match map_set(empty, "answer", "value") {
            Ok(root) => {
                    println(root)
                    drop(empty)
                    drop(root)
                    0
            },
            Err(status) => {
            drop(empty)
            status
            },
        }
        },
        Err(status) => {
        status
        },
    }
            }
        "#;
        let (mir, _) = compile_ordinary_map_owner_observer_v1(source);

        let wrong_profile = mir.route_receipt(crate::core::mir::MIR_BYTECODE_DIRECT_ROUTE_PROFILE);
        let errors = compile_mir_program_with_route_receipt(&mir, &wrong_profile)
            .expect_err("a generic bytecode route cannot authorize observer opcodes");
        assert!(errors.iter().any(|error| {
            error.message.contains(
                "ordinary Map owner observer v1 instructions require the exact route receipt",
            )
        }));

        let foreign_source = r#"
            func main() -> i32 {
    match map_new() {
        Ok(empty) => {
        match map_set(empty, "different", "value") {
            Ok(root) => {
                    println(root)
                    drop(empty)
                    drop(root)
                    0
            },
            Err(status) => {
            drop(empty)
            status
            },
        }
        },
        Err(status) => {
        status
        },
    }
            }
        "#;
        let (foreign_mir, _) = compile_ordinary_map_owner_observer_v1(foreign_source);
        let foreign_receipt = foreign_mir
            .ordinary_map_owner_lifecycle_observer_v1_route_receipt()
            .expect("foreign observer source has its own exact route receipt");
        assert_ne!(
            foreign_receipt.mir_digest,
            mir.route_receipt(crate::core::mir::ORDINARY_MAP_OWNER_LIFECYCLE_OBSERVER_V1_PROFILE)
                .mir_digest,
            "different exact observer keys must produce distinct route identities"
        );
        let errors = compile_mir_program_with_route_receipt(&mir, &foreign_receipt)
            .expect_err("a receipt for another observer MIR must be rejected");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains(crate::core::mir::MIR_ROUTE_RECEIPT_ERROR_CODE)
                    && error.message.contains("does not match MIR input")
            }),
            "foreign route receipt was not rejected with its digest-binding error: {errors:?}"
        );
    }

    #[test]
    fn map_any_owner_v1_emits_and_executes_a_distinct_i32_string_lifecycle() {
        // V1 deliberately seals one homogeneous payload type per root. Keep
        // the i32 and copied-String lifecycle examples in separate programs
        // so this regression exercises both admitted shapes without silently
        // widening the Checker contract to a mixed Any map.
        let sources = [
            r#"
                func main() -> i32 {
    match map_new() {
        Ok(empty) => {
        match map_set(empty, "answer", 42) {
            Ok(with_int) => {
                        let contains_int = has_key(with_int, "answer")
                        let without_int = map_remove(with_int, "answer")
                        let size = map_size(without_int)
                        drop(without_int)
                        size
            },
            Err(status) => {
            drop(empty)
            status
            },
        }
        },
        Err(status) => {
        status
        },
    }
                }
            "#,
            r#"
                func main() -> i32 {
    match map_new() {
        Ok(empty) => {
        match map_set(empty, "word", "map-any-owner") {
            Ok(with_string) => {
                        let contains_string = has_key(with_string, "word")
                        let without_string = map_remove(with_string, "word")
                        let size = map_size(without_string)
                        drop(without_string)
                        size
            },
            Err(status) => {
            drop(empty)
            status
            },
        }
        },
        Err(status) => {
        status
        },
    }
                }
            "#,
        ];
        let bytecodes = sources
            .iter()
            .map(|source| {
                let (_, checked) = parse_and_check(source).expect("MapAnyOwner v1 source check");
                let mir = MirProgram::from_checked_program(&checked).expect("MapAnyOwner v1 MIR");
                assert!(mir
                    .functions()
                    .values()
                    .any(|function| { function.ownership.has_checker_map_any_owner_actions() }));
                compile_mir_program(&mir).expect("MapAnyOwner v1 bytecode")
            })
            .collect::<Vec<_>>();
        assert!(bytecodes
            .iter()
            .all(|bytecode| bytecode.canonical_map_any_owner_v1_receipt.is_some()));
        let ops = bytecodes
            .iter()
            .flat_map(|bytecode| bytecode.functions.iter())
            .flat_map(|function| function.code.iter())
            .collect::<Vec<_>>();
        assert!(ops
            .iter()
            .any(|op| matches!(op, Op::MirMapAnyOwnerV1New { .. })));
        assert!(ops
            .iter()
            .any(|op| matches!(op, Op::MirMapAnyOwnerV1Set { .. })));
        assert!(ops
            .iter()
            .any(|op| matches!(op, Op::MirMapAnyOwnerV1Remove { .. })));
        assert!(ops
            .iter()
            .any(|op| matches!(op, Op::MirMapAnyOwnerV1Contains { .. })));
        assert!(ops
            .iter()
            .any(|op| matches!(op, Op::MirMapAnyOwnerV1Size { .. })));
        assert!(ops
            .iter()
            .any(|op| matches!(op, Op::MirMapAnyOwnerV1Drop { .. })));
        assert!(!ops.iter().any(|op| matches!(
            op,
            Op::MirMapRootNew { .. }
                | Op::MirMapRootSet { .. }
                | Op::MirMapRootRemove { .. }
                | Op::MirMapRootSize { .. }
                | Op::MirMapRootContains { .. }
                | Op::MirMapRootDrop { .. }
        )));

        for bytecode in bytecodes {
            let value = BytecodeVM::new(bytecode)
                .run_value()
                .expect("MapAnyOwner v1 bytecode execution");
            assert!(matches!(value, Value::Int(0)));
        }
    }

