    #[test]
    fn managed_any_vm_opcode_and_descriptor_tampering_fail_before_stdout() {
        use crate::core::mir::MirManagedAnyOperation;
        let mut proto = managed_any_vm_snapshot_fixture(Some(ConstValue::Int(42)));
        managed_any_vm_project_snapshot(&mut proto);
        let unpack = managed_any_vm_contract(&mut proto, MirManagedAnyOperation::UnpackI32);
        proto.emit(Op::MirManagedAnyOp {
            rd: Some(6),
            ra: 5,
            operation: MirManagedAnyOperation::UnpackI32,
            contract: unpack,
        });
        proto.emit(Op::Ret { ra: 6 });
        let mut program = managed_any_vm_program(proto);
        // Add an observable instruction before recapturing the pristine private snapshot.
        let program_mut = std::sync::Arc::make_mut(&mut program);
        let println = program_mut
            .builtin_names
            .iter()
            .position(|name| name == "println")
            .expect("println builtin") as super::super::instr::BuiltinIdx;
        let main = &mut program_mut.functions[0];
        let marker = main.add_const(ConstValue::Str("must not print".into()));
        main.code.insert(0, Op::LoadConst { rd: 8, idx: marker });
        main.code.insert(
            1,
            Op::CallBuiltin {
                rd: 9,
                builtin: println,
                args_base: 8,
                argc: 1,
            },
        );
        main.line_table = vec![0; main.code.len()];
        seal_managed_any_vm_program(program_mut);
        for drift in 0..3 {
            let mut forged = program.clone();
            let forged_mut = std::sync::Arc::make_mut(&mut forged);
            match drift {
                0 => {
                    let op = forged_mut.functions[0]
                        .code
                        .iter_mut()
                        .find(|op| matches!(op, Op::MirManagedAnyOp { .. }))
                        .expect("Any opcode");
                    let Op::MirManagedAnyOp { operation, .. } = op else {
                        unreachable!()
                    };
                    *operation = MirManagedAnyOperation::UnpackString;
                }
                1 => {
                    let ConstValue::ManagedAnyContract(shape) =
                        &mut forged_mut.functions[0].constants[unpack as usize]
                    else {
                        panic!("Any receipt")
                    };
                    shape.contract.descriptor_version = 2;
                }
                _ => {
                    let op = forged_mut.functions[0]
                        .code
                        .iter_mut()
                        .find(|op| matches!(op, Op::MirOrdinaryMapOwnedGetI32StringV1GetAny { .. }))
                        .expect("GetAny opcode");
                    let Op::MirOrdinaryMapOwnedGetI32StringV1GetAny { key, .. } = op else {
                        unreachable!()
                    };
                    *key = u16::MAX;
                }
            }
            let mut vm = BytecodeVM::new(forged);
            let error = vm.run_value().expect_err("drift must fail preflight");
            assert!(error
                .message()
                .contains("disagrees with its independent Checker receipt snapshot"));
            assert_eq!(vm.stdout(), "");
        }
    }

    #[test]
    fn mir_bytecode_register_abi_rejects_allocation_and_offset_overflow() {
        let (_, checked) = parse_and_check("func main() -> i32 { 42 }").expect("check");
        let program = MirProgram::from_checked_program(&checked).expect("canonical MIR");
        let owner = crate::core::NodeId("function:main".into());
        let function = program.functions().get(&owner).expect("main function");
        let mut emitter = FunctionEmitter {
            function,
            program: &program,
            indices: &BTreeMap::new(),
            ffi_indices: &BTreeMap::new(),
            proto: FunctionProto::new(function.owner.0.clone(), 0),
            registers: BTreeMap::new(),
            emitted_instruction_pc_ranges: BTreeMap::new(),
            block_starts: BTreeMap::new(),
            pending_jumps: Vec::new(),
            errors: Vec::new(),
            register_overflow_reported: false,
            constant_overflow_reported: false,
            map_any_owner_v1: false,
            ordinary_map_owned_get_i32_string_v1: false,
            ordinary_map_owned_any_v2: false,
            keys_snapshot_route_enabled: false,
            checked_get_route_enabled: false,
            dynamic_keys_get_route_enabled: false,
            direct_print_result_route_enabled: false,
            computed_string_key_owner_chain_route_enabled: false,
            map_set_drop_control_result_branch_route_enabled: false,
            values_local_index_i32_result_branch_route_enabled: false,
            ordinary_map_owned_get_result_branch_v3_route_enabled: false,
            values_producer_caller_sites: &[],
            values_crosscall_string_caller_sites: &[],
            values_result_crosscall_string_caller_proofs: &[],
            map_root_producer_caller_sites: &[],
            map_root_get_any_caller_sites: &[],
        };

        emitter.proto.register_count = u16::MAX;
        assert_eq!(emitter.alloc_reg(), 0);
        assert_eq!(emitter.proto.register_count, u16::MAX);
        assert_eq!(
            emitter.errors[0].message,
            "MIR bytecode register allocation exceeds u16 ABI"
        );
        assert_eq!(
            emitter.offset_reg(u16::MAX, 1, "variant payload"),
            None,
            "a register base plus field offset must not wrap"
        );
        assert!(emitter
            .errors
            .iter()
            .any(|error| error.message.contains("register index overflow")));
        assert_eq!(
            emitter.u16_abi(u16::MAX as usize, "field index"),
            Some(u16::MAX)
        );
        assert_eq!(
            emitter.u16_abi(u16::MAX as usize + 1, "field index"),
            None,
            "physical u16 fields must reject an unrepresentable index"
        );
        assert_eq!(
            emitter.u32_abi(u32::MAX as usize, "list capacity"),
            Some(u32::MAX)
        );
        assert_eq!(
            emitter.u32_abi(u32::MAX as usize + 1, "list capacity"),
            None,
            "physical u32 fields must reject an unrepresentable length"
        );
        assert_eq!(
            emitter.binding_parameter_index(usize::MAX, 1),
            None,
            "switch binding parameter arithmetic must not wrap"
        );
    }

