    #[test]
    fn canonical_scalar_ffi_uses_ast_free_bytecode_receipt() {
        let _guard = crate::tests::FfiEnvLock::lock();
        let source = include_str!("../../../tests/fixtures/mir_scalar_ffi_labs.mimi");
        let tokens = Lexer::new(source)
            .tokenize()
            .expect("lex scalar FFI fixture");
        let file = Parser::new(tokens)
            .parse_file()
            .expect("parse scalar FFI fixture");
        let checked = crate::core::check_program(&file).expect("check scalar FFI fixture");
        let mir = MirProgram::from_checked_program(&checked).expect("canonical scalar FFI MIR");
        assert_eq!(mir.ffi_calls().len(), 1);
        let bytecode = compile_mir_program(&mir).expect("canonical scalar FFI bytecode");
        assert!(bytecode.ast.is_none());
        assert_eq!(bytecode.canonical_ffi.len(), 1);
        assert_eq!(bytecode.canonical_ffi_bindings.len(), 1);
        let derived_receipt = bytecode
            .canonical_ffi_route_receipt
            .as_ref()
            .expect("direct canonical FFI adapter must derive a route receipt");
        assert_eq!(
            derived_receipt.profile,
            crate::core::mir::MIR_BYTECODE_DIRECT_ROUTE_PROFILE
        );
        assert_eq!(
            derived_receipt,
            &mir.route_receipt(crate::core::mir::MIR_BYTECODE_DIRECT_ROUTE_PROFILE),
            "direct adapter anchor must be the complete receipt for this MIR graph"
        );
        assert!(bytecode
            .canonical_ffi_bindings
            .iter()
            .all(|binding| { binding.route_receipt.as_ref() == Some(derived_receipt) }));
        assert_eq!(bytecode.canonical_ffi[0].symbol, "labs");
        assert_eq!(bytecode.canonical_ffi[0].abi, "C");
        assert_eq!(
            bytecode.canonical_ffi[0].arguments,
            vec![CanonicalFfiScalarType::I64],
            "bytecode ABI must follow the checker declaration TypeDesc"
        );
        assert_eq!(
            bytecode.canonical_ffi[0].result,
            CanonicalFfiScalarType::I64,
            "bytecode result ABI must follow the checker declaration TypeDesc"
        );
        assert!(matches!(
            bytecode.canonical_ffi[0].parameter_conversions.as_slice(),
            [crate::core::mir::MirFfiAbiConversion {
                from: crate::core::mir::types::MirAbiClass::Integer {
                    bits: 32,
                    signed: true
                },
                to: crate::core::mir::types::MirAbiClass::Integer {
                    bits: 64,
                    signed: true
                }
            }]
        ));
        assert!(matches!(
            bytecode.canonical_ffi[0].result_conversion,
            Some(crate::core::mir::MirFfiAbiConversion {
                from: crate::core::mir::types::MirAbiClass::Integer {
                    bits: 64,
                    signed: true
                },
                to: crate::core::mir::types::MirAbiClass::Integer {
                    bits: 64,
                    signed: true
                }
            })
        ));
        let mut vm = BytecodeVM::new(bytecode);
        let value = vm
            .run_value()
            .expect("AST-free canonical scalar FFI bytecode execution");
        assert!(matches!(value, Value::Int(0)));
        assert_eq!(vm.stdout(), "42\n");
    }

    #[test]
    fn canonical_scalar_ffi_route_receipt_is_pinned_in_bytecode_bindings() {
        let source = include_str!("../../../tests/fixtures/mir_scalar_ffi_labs.mimi");
        let file = Parser::new(
            Lexer::new(source)
                .tokenize()
                .expect("lex scalar FFI route receipt"),
        )
        .parse_file()
        .expect("parse scalar FFI route receipt");
        let checked = crate::core::check_program(&file).expect("check scalar FFI route receipt");
        let mir = MirProgram::from_checked_program(&checked)
            .expect("canonical scalar FFI route receipt MIR");
        let receipt = mir.route_receipt("r6-905-bytecode-route-v1");
        let bytecode = compile_mir_program_with_route_receipt(&mir, &receipt)
            .expect("canonical scalar FFI route receipt bytecode");
        assert!(bytecode
            .canonical_ffi_bindings
            .iter()
            .all(|binding| { binding.route_receipt.as_ref() == Some(&receipt) }));
        assert_eq!(
            bytecode.canonical_ffi_route_receipt.as_ref(),
            Some(&receipt)
        );

        // A mixed binding snapshot must stop at the VM boundary before the
        // duplicate call-site check or any dynamic library load. This models
        // a consumer that combines two independently admitted route views.
        let mut drifted = receipt.clone();
        drifted.profile = "r6-905-bytecode-route-drift".into();
        let mut uniform_bindings = bytecode.canonical_ffi_bindings.clone();
        for binding in &mut uniform_bindings {
            binding.route_receipt = Some(drifted.clone());
        }
        let mut uniform_vm = BytecodeVM::new(bytecode.clone());
        uniform_vm.replace_canonical_ffi_tables_for_test_only(
            bytecode.canonical_ffi.clone(),
            uniform_bindings,
        );
        let anchor_error = uniform_vm
            .run_value()
            .expect_err("uniform forged route receipt must fail closed");
        assert_eq!(
            anchor_error.diagnostic_code(),
            crate::core::mir::MIR_ROUTE_RECEIPT_ERROR_CODE
        );
        assert!(
            anchor_error
                .to_string()
                .contains("disagrees with program anchor"),
            "{anchor_error}"
        );

        let mut forged_bindings = bytecode.canonical_ffi_bindings.clone();
        let mut forged = forged_bindings[0].clone();
        forged.route_receipt = Some(drifted);
        forged_bindings.push(forged);
        let descriptors = bytecode.canonical_ffi.clone();
        let mut vm = BytecodeVM::new(bytecode);
        vm.replace_canonical_ffi_tables_for_test_only(descriptors, forged_bindings);
        let error = vm
            .run_value()
            .expect_err("mixed canonical route receipts must fail closed");
        assert_eq!(
            error.diagnostic_code(),
            crate::core::mir::MIR_ROUTE_RECEIPT_ERROR_CODE
        );
        assert!(
            error.to_string().contains("mixes route receipt identities"),
            "{error}"
        );
    }

    /// R6-1107 L2 negatives: the two receipt-anchoring branches the pinned
    /// test does not reach, plus the empty-binding-manifest table shape.
    /// A program anchor without matching binding receipts, a binding receipt
    /// without a program anchor, and a descriptor table without any binding
    /// manifest must all fail closed at the VM boundary with
    /// MIR_ROUTE_RECEIPT_ERROR_CODE before any dynamic library load.
    #[test]
    fn canonical_scalar_ffi_route_receipt_anchor_gaps_fail_closed() {
        let source = include_str!("../../../tests/fixtures/mir_scalar_ffi_labs.mimi");
        let file = Parser::new(
            Lexer::new(source)
                .tokenize()
                .expect("lex scalar FFI anchor gaps"),
        )
        .parse_file()
        .expect("parse scalar FFI anchor gaps");
        let checked = crate::core::check_program(&file).expect("check scalar FFI anchor gaps");
        let mir = MirProgram::from_checked_program(&checked)
            .expect("canonical scalar FFI anchor gaps MIR");
        let receipt = mir.route_receipt("r6-1107-bytecode-route-v1");
        let bytecode = compile_mir_program_with_route_receipt(&mir, &receipt)
            .expect("canonical scalar FFI anchor gaps bytecode");
        let descriptors = bytecode.canonical_ffi.clone();

        // Act 1: descriptor table without any binding manifest.
        let mut vm = BytecodeVM::new(bytecode.clone());
        vm.replace_canonical_ffi_tables_for_test_only(descriptors.clone(), Vec::new());
        let error = vm
            .run_value()
            .expect_err("descriptor table without binding manifest must fail closed");
        assert_eq!(
            error.diagnostic_code(),
            crate::core::mir::MIR_ROUTE_RECEIPT_ERROR_CODE
        );
        assert!(
            error
                .to_string()
                .contains("canonical FFI binding manifest is missing"),
            "{error}"
        );

        // Act 2: program anchor present, every binding receipt stripped —
        // the anchor would silently dangle if the per-site walk ran.
        let mut unanchored_bindings = bytecode.canonical_ffi_bindings.clone();
        for binding in &mut unanchored_bindings {
            binding.route_receipt = None;
        }
        let mut vm = BytecodeVM::new(bytecode.clone());
        vm.replace_canonical_ffi_tables_for_test_only(descriptors.clone(), unanchored_bindings);
        let error = vm
            .run_value()
            .expect_err("dangling program anchor must fail closed");
        assert_eq!(
            error.diagnostic_code(),
            crate::core::mir::MIR_ROUTE_RECEIPT_ERROR_CODE
        );
        assert!(
            error
                .to_string()
                .contains("canonical FFI program route receipt is missing from binding manifest"),
            "{error}"
        );

        // Act 3: binding receipts present, program anchor removed — a
        // binding snapshot must never self-certify without the anchor.
        let mut vm = BytecodeVM::new(bytecode);
        vm.replace_canonical_ffi_route_receipt_anchor_for_test_only(None);
        let error = vm
            .run_value()
            .expect_err("binding receipt without program anchor must fail closed");
        assert_eq!(
            error.diagnostic_code(),
            crate::core::mir::MIR_ROUTE_RECEIPT_ERROR_CODE
        );
        assert!(
            error
                .to_string()
                .contains("canonical FFI binding route receipt has no program anchor"),
            "{error}"
        );
    }

    #[test]
    fn canonical_scalar_ffi_route_manifest_replay_keeps_manifest_diagnostic_code() {
        let source = include_str!("../../../tests/fixtures/mir_scalar_ffi_labs.mimi");
        let file = Parser::new(
            Lexer::new(source)
                .tokenize()
                .expect("lex scalar FFI manifest replay"),
        )
        .parse_file()
        .expect("parse scalar FFI manifest replay");
        let checked = crate::core::check_program(&file).expect("check scalar FFI manifest replay");
        let mir = MirProgram::from_checked_program(&checked)
            .expect("canonical scalar FFI manifest replay MIR");
        let receipt = mir.route_receipt("r6-933-bytecode-manifest-replay-v1");
        let mut bytecode = compile_mir_program_with_route_receipt(&mir, &receipt)
            .expect("canonical scalar FFI manifest replay bytecode");
        let forged = std::sync::Arc::make_mut(&mut bytecode);
        let mut invalid = receipt;
        invalid.mir_digest = "not-a-valid-lowercase-hex-digest".into();
        forged.canonical_ffi_route_receipt = Some(invalid.clone());
        for binding in &mut forged.canonical_ffi_bindings {
            binding.route_receipt = Some(invalid.clone());
        }

        let error = BytecodeVM::new(bytecode)
            .run_value()
            .expect_err("invalid route manifest must fail before execution");
        assert_eq!(
            error.diagnostic_code(),
            crate::core::mir::MIR_ROUTE_MANIFEST_ERROR_CODE
        );
        let diagnostic = error.to_diagnostic();
        assert_eq!(
            diagnostic.code.as_deref(),
            Some(crate::core::mir::MIR_ROUTE_MANIFEST_ERROR_CODE)
        );
        assert_eq!(
            diagnostic
                .origin
                .as_ref()
                .and_then(|origin| origin.rule.as_deref()),
            Some("mir.route")
        );
    }

