    #[test]
    fn canonical_ffi_binding_materialization_rejects_register_window_out_of_frame() {
        let source = include_str!("../../../tests/fixtures/mir_scalar_ffi_labs.mimi");
        let file = Parser::new(Lexer::new(source).tokenize().expect("lex scalar FFI"))
            .parse_file()
            .expect("parse scalar FFI");
        let checked = crate::core::check_program(&file).expect("check scalar FFI");
        let mir = MirProgram::from_checked_program(&checked).expect("canonical scalar FFI MIR");
        let bytecode = compile_mir_program(&mir).expect("canonical scalar FFI bytecode");
        let main_idx = bytecode
            .functions
            .iter()
            .position(|function| function.name == "function:main")
            .expect("main function");
        let call_idx = bytecode.functions[main_idx]
            .code
            .iter()
            .position(|op| matches!(op, Op::CallCanonicalExtern { .. }))
            .expect("canonical FFI call");

        let mut forged_rd = bytecode.functions.clone();
        let register_count = forged_rd[main_idx].register_count;
        if let Op::CallCanonicalExtern { rd, .. } = &mut forged_rd[main_idx].code[call_idx] {
            *rd = register_count;
        } else {
            panic!("binding must point at a canonical extern");
        }
        let errors = super::materialize_canonical_ffi_bindings(&forged_rd, &bytecode.canonical_ffi)
            .expect_err("an out-of-frame result register must fail at construction");
        assert!(
            errors
                .iter()
                .any(|error| error.message.contains("result register")
                    && error.message.contains("outside function frame")),
            "{errors:?}"
        );

        let mut forged_args = bytecode.functions.clone();
        let register_count = forged_args[main_idx].register_count;
        if let Op::CallCanonicalExtern {
            args_base, argc, ..
        } = &mut forged_args[main_idx].code[call_idx]
        {
            *args_base = register_count;
            *argc = 1;
        } else {
            panic!("binding must point at a canonical extern");
        }
        let errors =
            super::materialize_canonical_ffi_bindings(&forged_args, &bytecode.canonical_ffi)
                .expect_err("an out-of-frame argument window must fail at construction");
        assert!(
            errors
                .iter()
                .any(|error| error.message.contains("argument register window")
                    && error.message.contains("exceeds function frame")),
            "{errors:?}"
        );
    }

    #[test]
    fn canonical_ffi_binding_materialization_rejects_frame_shape_and_arity_drift() {
        let source = include_str!("../../../tests/fixtures/mir_scalar_ffi_labs.mimi");
        let file = Parser::new(Lexer::new(source).tokenize().expect("lex scalar FFI"))
            .parse_file()
            .expect("parse scalar FFI");
        let checked = crate::core::check_program(&file).expect("check scalar FFI");
        let mir = MirProgram::from_checked_program(&checked).expect("canonical scalar FFI MIR");
        let bytecode = compile_mir_program(&mir).expect("canonical scalar FFI bytecode");
        let main_idx = bytecode
            .functions
            .iter()
            .position(|function| function.name == "function:main")
            .expect("main function");
        let call_idx = bytecode.functions[main_idx]
            .code
            .iter()
            .position(|op| matches!(op, Op::CallCanonicalExtern { .. }))
            .expect("canonical FFI call");

        let mut forged_frame = bytecode.functions.clone();
        let register_count = forged_frame[main_idx].register_count;
        forged_frame[main_idx].param_count = register_count.saturating_add(1);
        let errors =
            super::materialize_canonical_ffi_bindings(&forged_frame, &bytecode.canonical_ffi)
                .expect_err("a frame with fewer registers than parameter slots must fail");
        assert!(
            errors
                .iter()
                .any(|error| error.message.contains("parameter slot")
                    && error.message.contains("register(s)")),
            "{errors:?}"
        );

        let mut forged_arity = bytecode.functions.clone();
        if let Op::CallCanonicalExtern { argc, .. } = &mut forged_arity[main_idx].code[call_idx] {
            *argc = 0;
        } else {
            panic!("binding must point at a canonical extern");
        }
        let errors =
            super::materialize_canonical_ffi_bindings(&forged_arity, &bytecode.canonical_ffi)
                .expect_err("a call arity differing from its descriptor must fail");
        assert!(
            errors
                .iter()
                .any(|error| error.message.contains("argument count")
                    && error.message.contains("descriptor arity")),
            "{errors:?}"
        );

        let mut forged_mut_params = bytecode.functions.clone();
        forged_mut_params[main_idx].mut_param_indices =
            vec![forged_mut_params[main_idx].param_count];
        let errors =
            super::materialize_canonical_ffi_bindings(&forged_mut_params, &bytecode.canonical_ffi)
                .expect_err("a mutable parameter register outside the frame must fail");
        assert!(
            errors
                .iter()
                .any(|error| error.message.contains("mutable parameter register")
                    && error.message.contains("parameter slot")),
            "{errors:?}"
        );

        let mut forged_contracts = bytecode.functions.clone();
        forged_contracts[main_idx].has_requires = true;
        forged_contracts[main_idx].requires_funcs = vec![u32::MAX];
        let errors =
            super::materialize_canonical_ffi_bindings(&forged_contracts, &bytecode.canonical_ffi)
                .expect_err("an out-of-range contract function must fail at construction");
        assert!(
            errors.iter().any(|error| {
                error.message.contains("requires contract function")
                    && error
                        .message
                        .contains("outside the bytecode function table")
            }),
            "{errors:?}"
        );
    }

