    #[test]
    fn canonical_scalar_ffi_bytecode_rejects_incoherent_frame_and_descriptor_arity() {
        let source = include_str!("../../../tests/fixtures/mir_scalar_ffi_labs.mimi");
        let file = Parser::new(Lexer::new(source).tokenize().expect("lex scalar FFI"))
            .parse_file()
            .expect("parse scalar FFI");
        let checked = crate::core::check_program(&file).expect("check scalar FFI");
        let mir = MirProgram::from_checked_program(&checked).expect("canonical scalar FFI MIR");
        let original = compile_mir_program(&mir).expect("canonical scalar FFI bytecode");

        let mut forged_frame = original.clone();
        let binding = forged_frame.canonical_ffi_bindings[0].clone();
        let function_idx = binding.function as usize;
        let invalid_param_count = binding.register_count.saturating_add(1);
        let forged = std::sync::Arc::make_mut(&mut forged_frame);
        forged.functions[function_idx].param_count = invalid_param_count;
        forged.canonical_ffi_bindings[0].param_count = invalid_param_count;
        let error = BytecodeVM::new(forged_frame)
            .run_value()
            .expect_err("a binding frame with fewer registers than parameters must fail");
        assert!(error.to_string().contains("parameter slot"), "{error}");

        let mut forged_arity = original.clone();
        let binding = forged_arity.canonical_ffi_bindings[0].clone();
        let function_idx = binding.function as usize;
        let pc = binding.pc as usize;
        let forged = std::sync::Arc::make_mut(&mut forged_arity);
        if let Op::CallCanonicalExtern {
            args_base, argc, ..
        } = &mut forged.functions[function_idx].code[pc]
        {
            *args_base = 0;
            *argc = 0;
            forged.canonical_ffi_bindings[0].args_base = 0;
            forged.canonical_ffi_bindings[0].argc = 0;
        } else {
            panic!("binding must point at a canonical extern");
        }
        let error = BytecodeVM::new(forged_arity)
            .run_value()
            .expect_err("a call arity differing from its descriptor must fail");
        assert!(error.to_string().contains("descriptor arity"), "{error}");

        let mut forged_mut_params = original.clone();
        let binding = forged_mut_params.canonical_ffi_bindings[0].clone();
        let function_idx = binding.function as usize;
        let invalid_param_index = binding.param_count;
        let forged = std::sync::Arc::make_mut(&mut forged_mut_params);
        forged.functions[function_idx].mut_param_indices = vec![invalid_param_index];
        forged.canonical_ffi_bindings[0].mut_param_indices = vec![invalid_param_index];
        let error = BytecodeVM::new(forged_mut_params)
            .run_value()
            .expect_err("a mutable parameter register outside the frame must fail");
        assert!(
            error.to_string().contains("mutable parameter register"),
            "{error}"
        );

        let mut forged_contracts = original.clone();
        let binding = forged_contracts.canonical_ffi_bindings[0].clone();
        let function_idx = binding.function as usize;
        let invalid_contract_func = u32::MAX;
        let forged = std::sync::Arc::make_mut(&mut forged_contracts);
        forged.functions[function_idx].has_requires = true;
        forged.functions[function_idx].requires_funcs = vec![invalid_contract_func];
        forged.canonical_ffi_bindings[0].has_requires = true;
        forged.canonical_ffi_bindings[0].requires_funcs = vec![invalid_contract_func];
        let error = BytecodeVM::new(forged_contracts)
            .run_value()
            .expect_err("an out-of-range contract function must fail before execution");
        assert!(
            error.to_string().contains("requires contract function")
                && error
                    .to_string()
                    .contains("outside the bytecode function table"),
            "{error}"
        );
    }

    #[test]
    fn canonical_scalar_ffi_missing_descriptor_never_uses_compatibility_runtime() {
        let source = include_str!("../../../tests/fixtures/mir_scalar_ffi_labs.mimi");
        let file = Parser::new(Lexer::new(source).tokenize().unwrap())
            .parse_file()
            .unwrap();
        let checked = crate::core::check_program(&file).unwrap();
        let mir = MirProgram::from_checked_program(&checked).unwrap();
        let mut bytecode = compile_mir_program(&mir).unwrap();
        let forged = std::sync::Arc::make_mut(&mut bytecode);
        forged.canonical_ffi.clear();
        forged.extern_names.push("legacy_tripwire".into());
        let error = BytecodeVM::new(bytecode)
            .run_value()
            .expect_err("canonical FFI must reject its missing descriptor");
        assert!(
            error.to_string().contains("canonical FFI binding manifest"),
            "{error}"
        );
        assert_eq!(
            error.diagnostic_code(),
            crate::core::mir::MIR_ROUTE_RECEIPT_ERROR_CODE
        );
        let diagnostic = error.to_diagnostic();
        assert_eq!(
            diagnostic.code.as_deref(),
            Some(crate::core::mir::MIR_ROUTE_RECEIPT_ERROR_CODE)
        );
        assert_eq!(
            diagnostic
                .origin
                .as_ref()
                .and_then(|origin| origin.rule.as_deref()),
            Some("mir.route")
        );
        assert!(!error.to_string().contains("legacy_tripwire"));
    }

